== guards.js word lists ==
10:  const BAD = /akzeptieren und fortfahren|umfrage|bewert|feedback|survey|rate us|teilnehmen|zur befragung/;
15:      /vorübergehend nicht verfügbar|service unavailable|bad gateway|gateway timeout|interner fehler|internal server error|fehler 50\d|error 50\d/i.test(body);
16:    let retry = null;
18:      const a = [...document.querySelectorAll("a[href]")].find((x) => /erneut|nochmal|retry|wiederholen/i.test(txt(x)));
19:      retry = a ? a.getAttribute("href") : null;
21:    const consent = !hasPassword && /cookie/i.test(body) &&
22:      clickables(document).some((b) => visible(b) && /cookie|akzeptier|zustimm|einverstanden|accept/.test(name(b)));
24:    return { login: hasPassword, error_page: errorPage, retry_href: retry, consent, pending_dialogs: pending };
29:    const pick = buttons.find((b) => /notwendig|necessary|essential|erforderlich/.test(name(b)) && /akzept|accept|nur|only|zulassen|allow/.test(name(b)))
30:      || buttons.find((b) => /notwendig|necessary/.test(name(b)))
31:      || buttons.find((b) => /akzeptier|accept|zustimm|einverstanden/.test(name(b)) && !BAD.test(name(b)));
42:      const close = buttons.find((b) => /schlie|close|^\s*[×✕x]\s*$|später|nicht jetzt|nein danke|no thanks|abbrechen|ausblenden/.test(name(b).trim()) && !BAD.test(name(b)));

== review.py number handling ==
"""Compare what the portal recorded (the review page, extracted by the model) with the answer we computed.

Pure functions, unit-tested. Values on the page are raw strings in the page's number format; the default locale is
German (the portals' format), explicit locale tags win.
"""
from decimal import Decimal

